{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "དཔྱིད་ཐིག་ལས།",
      "head": "གནས་འདི་རྣམས་སུ་མཁའ་འགྲོ་རྣམས། །",
      "tail": "ཉེ་བའི་དུར་ཁྲོད་ཡང་དག་གནས། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཕྱག་རྡོར་བསྟོད་འགྲེལ་ལས།",
      "head": "ཐིམ་པ་དང་ལོངས་སྤྱོད་པ་དང་བདག་པོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རླུང་ཁྲག་འདྲེས་པ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཧེ་བཛྲ་ལས།",
      "head": "བཅོ་ལྔ་ཆ་ཡི་བདག་ཉིད་ཕྱིར། །",
      "tail": "རྣལ་འབྱོར་མ་རྣམས་དེ་ཡི་ཆ། །"
    },
    {
      "label": "QUOTE",
      "frame": "དུས་འཁོར་ལས།",
      "head": "མཐེ་བོའི་ཚིགས་ནས་གཙུག་ཏོར་དག་ཏུ་ཉ་ཡི་མཐར་ནི་རང་སེམས་འགྲོ་སྟེ་ཚེས་ཀྱི་དབང་གིས་སོ། །",
      "tail": "ནག་པོའི་ཕྱོགས་ཀྱི་མཐའ་རུའོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "བདེ་མཆོག་སྡོམ་འབྱུང་ལས།",
      "head": "ཨ་ཨཱ། ཨི་ཨཱི། ཨུ་ཨཱུ། ར໏་རཱ໏། ལི་ལཱི། ཨེ་ཨཻ། ཨོ་ཨཽ། ཨཾ་གི་ཡི་གེའི་རིམ་པས། ཡར་ངོ་ཡི་ནི་ཚེས་གཅིག་ལ། །",
      "tail": "རྐང་པའི་སོར་མོར་ཡི་གེ་ཨ། །"
    },
    {
      "label": "QUOTE",
      "frame": "སྨན་གྱི་བསྟན་བཅོས་ལས་ཀྱང་།",
      "head": "ཀུན་ཏུ་ཁྱམས་པའི་བླ་གནས་ཀྱི་རྩ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བརྟག་གཉིས་ཀྱི་ལུང་།",
      "head": "གཅིག་དང་དུ་མ་བྲལ་བ་ཡི། །སྐད་ཅིག་གཅིག་ལ་མཆོག་དགའ་བ། །",
      "tail": "ཀུན་མཁྱེན་ཡེ་ཤེས་དེ་ལྟ་བུ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྩ་རྒྱུད་ལས།",
      "head": "མཆོག་ཏུ་མི་འགྱུར་ཉི་ཁྲི་དང་། །",
      "tail": "རང་ཉིད་རྡོ་རྗེ་སེམས་པར་འགྱུར། །"
    }
  ]
}
